/**
 * Digging and placing on a planet whose host lets visitors edit: what the
 * planet offers (its description's `edit`, `changes`, and each area's
 * `nodes`, `icons` and `node`), what the world's `hints:planet` ask of the
 * shell, the write the shell sends, and the changes it hears of.
 *
 * Hints are presentation only. What a visitor may do is decided by the
 * planet's host, which refuses whatever its policy, reach or blocks do not
 * allow; a world can narrow what the shell offers, never widen it.
 *
 * The write is a session write: the visitor's pass for this planet as a
 * bearer, the node the visitor saw in `If-Match`, and where they stand, so
 * the host checks the reach. A pass (signIn.ts) is made by the planet's pass
 * issuer for the planet's client and write origin, and is the planet's
 * alone: kept under the pass issuer, the planet's client and the write
 * origin together, and sent to that origin and no other. A planet takes
 * writes on one origin, over https (or in clear on this machine); an area
 * that writes anywhere else is not offered.
 */

import { resolveWorldUri } from '../../veml/uriResolve';

export interface PlanetEditArea {
  /** The region drawn in the area, as the planet's changes name it. */
  region?: string;
  /** A chunk's nodes, by its lowest corner. */
  nodes(x: number, y: number, z: number): string;
  /** A block's icon. */
  icon(name: string): string;
  /** Where a node is written. */
  node(x: number, y: number, z: number): string;
  /** Where the area is woken on arrival, on the write origin; absent where the planet never stops it. */
  wake?: string;
}

export interface PlanetEditInfo {
  policy: 'signed-in' | 'allow-list';
  /** The pass issuer whose passes the planet takes (signIn.ts). */
  issuer?: string;
  /** How far a visitor reaches, in metres. */
  reach: number;
  /** The list of blocks offered for placing, absolute. */
  blocks: string;
  /** The WorldSync room the planet tells its changes in. */
  changes?: { address: string; session: string };
  /** The planet's own client at the pass issuer: the audience of its passes (signIn.ts); absent, the shell offers no sign-in. */
  signIn?: { clientId: string };
  /** The one origin the planet takes writes on, and where its sign-in returns. */
  writeOrigin?: string;
  /** Where this description was read from: the write origin must vouch for it (`writesVouched`). */
  description: string;
  /** By slot key (`face,ax,az`). */
  areas: Map<string, PlanetEditArea>;
}

const originOf = (url: string): string | undefined => {
  try {
    return new URL(url).origin;
  } catch {
    return undefined;
  }
};

/** A URL's origin where a token or a sign-in may go: https, or in clear only on this machine. */
export function trustedOrigin(url: string): string | undefined {
  try {
    const u = new URL(url);
    if (u.protocol === 'https:' || (u.protocol === 'http:' && (u.hostname === 'localhost' || u.hostname === '127.0.0.1' || u.hostname === '[::1]'))) return u.origin;
  } catch {
    // Not a URL.
  }
  return undefined;
}

const fill = (t: string, x: number, y: number, z: number) => t.replace('{x}', String(x)).replace('{y}', String(y)).replace('{z}', String(z));

/** A node's write route: `…/area/<region>/node/<x>_<y>_<z>` and nothing after it, so a token reaches no other route. */
const NODE_ROUTE = /\/area\/[a-z0-9-]+\/node\/-?\d+_-?\d+_-?\d+$/;
const isNodeRoute = (url: string): boolean => {
  try {
    const u = new URL(url);
    return u.search === '' && u.hash === '' && NODE_ROUTE.test(u.pathname);
  } catch {
    return false;
  }
};

/** An area's wake route: `…/area/<region>/wake` and nothing after it. */
const isWakeRoute = (url: string, region: string): boolean => {
  try {
    const u = new URL(url);
    return u.search === '' && u.hash === '' && u.pathname.endsWith(`/area/${region}/wake`);
  } catch {
    return false;
  }
};

/** Where a write origin lists the planet descriptions it takes edits for. */
export const PLANET_WRITES = '/.well-known/planet-writes.json';

/**
 * Whether the planet's write origin vouches for this description: it lists
 * the description's address among those it takes edits for. Without it a
 * description could copy another planet's issuer, client and write origin,
 * and have its visitors edit that planet in their own names.
 */
export async function writesVouched(edit: Pick<PlanetEditInfo, 'writeOrigin' | 'description'>, fetchImpl: (url: string) => Promise<Response>): Promise<boolean> {
  if (!edit.writeOrigin) return false;
  try {
    const res = await fetchImpl(`${edit.writeOrigin}${PLANET_WRITES}`);
    if (!res.ok) return false;
    const listed = ((await res.json()) as { descriptions?: unknown }).descriptions;
    return Array.isArray(listed) && listed.includes(edit.description);
  } catch {
    return false;
  }
}

/** What the planet's description offers for editing; undefined where it offers none. */
export function readPlanetEdit(json: unknown, url: string): PlanetEditInfo | undefined {
  const d = (json && typeof json === 'object' ? json : {}) as Record<string, unknown>;
  const e = d.edit as Record<string, unknown> | undefined;
  if (!e || (e.policy !== 'signed-in' && e.policy !== 'allow-list') || typeof e.blocks !== 'string') return undefined;
  const own = originOf(url);
  const areas = new Map<string, PlanetEditArea>();
  let writeOrigin: string | undefined;
  const surface = (d.surface ?? {}) as { areas?: unknown };
  for (const raw of Array.isArray(surface.areas) ? surface.areas : []) {
    const a = (raw ?? {}) as Record<string, unknown>;
    const m = typeof a.slot === 'string' ? /^(px|nx|py|ny|pz|nz),(\d+),(\d+)$/.exec(a.slot) : null;
    if (!m || typeof a.nodes !== 'string' || typeof a.icons !== 'string' || typeof a.node !== 'string') continue;
    const nodes = a.nodes, icons = a.icons, node = a.node;
    // Reads come from the description's own origin, as its chunks do; writes go wherever the planet's host is.
    if (originOf(resolveWorldUri(fill(nodes, 0, 0, 0), url)) !== own || originOf(resolveWorldUri(icons.replace('{name}', 'x'), url)) !== own) continue;
    // Writes carry the visitor's token: to one origin only, the first area's, never in clear off this machine, and only at the area's node route.
    if (typeof a.region !== 'string' || !node.endsWith(`/area/${a.region}/node/{x}_{y}_{z}`) || !isNodeRoute(resolveWorldUri(fill(node, 0, 0, 0), url))) continue;
    const writes = trustedOrigin(resolveWorldUri(fill(node, 0, 0, 0), url));
    if (!writes || (writeOrigin !== undefined && writes !== writeOrigin)) continue;
    writeOrigin = writes;
    // The wake route takes the pass too: only the node route's own shape, on the same origin; anything else is read as absent.
    const wake = typeof a.wake === 'string' && a.wake === node.replace('node/{x}_{y}_{z}', 'wake') ? resolveWorldUri(a.wake, url) : undefined;
    areas.set(`${m[1]},${Number(m[2])},${Number(m[3])}`, {
      ...(typeof a.region === 'string' ? { region: a.region } : {}),
      nodes: (x, y, z) => resolveWorldUri(fill(nodes, x, y, z), url),
      icon: (n) => resolveWorldUri(icons.replace('{name}', encodeURIComponent(n)), url),
      node: (x, y, z) => resolveWorldUri(fill(node, x, y, z), url),
      ...(wake && originOf(wake) === writes && isWakeRoute(wake, a.region) ? { wake } : {}),
    });
  }
  const c = d.changes as Record<string, unknown> | undefined;
  const clientId = ((e.signIn ?? {}) as Record<string, unknown>).clientId;
  const reach = typeof e.reach === 'number' && Number.isFinite(e.reach) && e.reach > 0 ? e.reach : 5;
  return {
    policy: e.policy,
    ...(typeof e.issuer === 'string' ? { issuer: e.issuer } : {}),
    reach,
    blocks: resolveWorldUri(e.blocks, url),
    ...(typeof clientId === 'string' && clientId !== '' ? { signIn: { clientId } } : {}),
    ...(writeOrigin ? { writeOrigin } : {}),
    description: url,
    ...(c && c.type === 'worldsync' && typeof c.address === 'string' && typeof c.session === 'string' ? { changes: { address: c.address, session: c.session } } : {}),
    areas,
  };
}

/** What the planet offers this visitor. */
export interface PlanetEditOffer {
  policy: string;
  reach: number;
  blocks: string[];
  /** Whether the visitor holds a token for the planet's issuer. */
  signedIn: boolean;
}

/** What the shell offers, after the world's hints. */
export interface EditAsk {
  dig: boolean;
  place: boolean;
  reach: number;
  blocks: string[];
  bar: boolean;
  menu: boolean;
  /** Each a key's name, as `KeyboardEvent.key` gives it lower-cased, or `mouse-left`, `mouse-right`, `mouse-middle`. */
  keys: { dig: string; place: string; menu: string };
}

export const DEFAULT_EDIT_KEYS = { dig: 'mouse-left', place: 'mouse-right', menu: 'e' };

/**
 * The world's `planet.edit`, `planet.reach`, `planet.blocks`,
 * `planet.edit-bar`, `planet.edit-menu` and `planet.edit-keys`, read
 * against what the planet offers. `auto` takes the planet's own.
 */
export function editAskOf(hint: (name: string) => string | null, offer: PlanetEditOffer): EditAsk {
  const h = (n: string) => (hint(n) ?? 'auto').trim();
  const mode = h('planet.edit');
  const may = offer.signedIn && mode !== 'none';
  const r = Number(h('planet.reach'));
  const listed = h('planet.blocks');
  const named = listed === 'auto' ? offer.blocks : listed.split(/\s+/).filter((b) => offer.blocks.includes(b));
  const k = h('planet.edit-keys').toLowerCase().split(/\s+/);
  return {
    dig: may && (mode === 'auto' || mode === 'both' || mode === 'dig'),
    place: may && (mode === 'auto' || mode === 'both' || mode === 'place'),
    reach: h('planet.reach') !== 'auto' && Number.isFinite(r) ? Math.min(r, offer.reach) : offer.reach,
    blocks: named,
    bar: h('planet.edit-bar') !== 'none',
    menu: h('planet.edit-menu') !== 'none',
    keys: k.length === 3 && k.every((x) => x.length > 0) ? { dig: k[0]!, place: k[1]!, menu: k[2]! } : { ...DEFAULT_EDIT_KEYS },
  };
}

/** Where the shell keeps a planet's token: under its issuer, its client there and its write origin, together. */
export function planetTokenKey(issuer: string, clientId: string, writeOrigin: string): string {
  return `webverse:planet-session:${JSON.stringify([issuer, clientId, writeOrigin])}`;
}

/** The visitor's token for this planet, as the shell keeps it; null with none, or one past its expiry. */
export function planetTokenFor(edit: Pick<PlanetEditInfo, 'issuer' | 'signIn' | 'writeOrigin'>, read: (key: string) => string | null): string | null {
  if (!edit.issuer || !edit.signIn || !edit.writeOrigin) return null;
  try {
    return liveToken(read(planetTokenKey(edit.issuer, edit.signIn.clientId, edit.writeOrigin)));
  } catch {
    return null;
  }
}

/** A token, or null where there is none or its `exp` has passed. Its expiry is read only to stop offering what it can no longer do; whoever takes it checks it again. */
export function liveToken(token: string | null | undefined): string | null {
  if (!token) return null;
  try {
    const part = token.split('.')[1];
    const exp = part ? (JSON.parse(atob(part.replace(/-/g, '+').replace(/_/g, '/'))) as { exp?: unknown }).exp : undefined;
    if (typeof exp === 'number' && exp * 1000 <= Date.now()) return null;
  } catch {
    // Not a token whose expiry can be read here: whoever takes it decides.
  }
  return token;
}

export interface EditSend {
  url: string;
  /** The planet's write origin: the token goes there and nowhere else. */
  writeOrigin: string;
  token: string;
  op: 'dig' | 'place';
  /** The node the visitor saw there. */
  expect: string;
  node?: string;
  /** The block's variant: its turn, shape or colour, as the planet numbers it. */
  variant?: number;
  /** Where the visitor's eye is, in the area's blocks. */
  from: [number, number, number];
  /** A place's: the part-block it is built on, a face away, and its name as the visitor saw it; the planet makes it whole. */
  on?: { at: [number, number, number]; node: string };
}

export type EditOutcome =
  | { result: 'applied'; node?: string; filled?: string }
  | { result: 'accepted' }
  | { result: 'refused'; reason: string; node?: string };

/** Send one edit and read the planet's answer. Never throws: a failure is a refusal the visitor is told of. */
export async function sendEdit(fetchImpl: (url: string, init?: RequestInit) => Promise<Response>, e: EditSend): Promise<EditOutcome> {
  if (trustedOrigin(e.url) === undefined || originOf(e.url) !== e.writeOrigin || !isNodeRoute(e.url)) return { result: 'refused', reason: 'refused' };
  let res: Response;
  try {
    res = await fetchImpl(e.url, {
      method: e.op === 'dig' ? 'DELETE' : 'PUT',
      headers: { authorization: `Bearer ${e.token}`, 'if-match': `"${e.expect}"`, 'content-type': 'application/json' },
      body: JSON.stringify(e.op === 'dig' ? { from: e.from } : { node: e.node, variant: e.variant ?? 0, from: e.from, ...(e.on ? { on: e.on } : {}) }),
    });
  } catch {
    return { result: 'refused', reason: 'unavailable' };
  }
  let body: { node?: unknown; reason?: unknown; filled?: unknown } = {};
  try {
    body = (await res.json()) as typeof body;
  } catch {
    // No body to read: the status says enough.
  }
  const node = typeof body?.node === 'string' ? { node: body.node } : {};
  if (res.status === 200) return { result: 'applied', ...node, ...(typeof body?.filled === 'string' && body.filled ? { filled: body.filled } : {}) };
  if (res.status === 202) return { result: 'accepted' };
  if (res.status === 401) return { result: 'refused', reason: 'sign-in' };
  // A part of the planet asleep says so, and starts: the one server error with a reason the shell acts on.
  if (res.status === 503 && body?.reason === 'region-not-running') return { result: 'refused', reason: 'region-not-running' };
  if (res.status >= 500) return { result: 'refused', reason: 'unavailable' };
  return { result: 'refused', reason: typeof body?.reason === 'string' ? body.reason : 'refused', ...node };
}

/** A chunk's nodes, as the planet serves them for picking; coordinates within the chunk, 0 to 15. */
export interface MapblockNodes {
  name(x: number, y: number, z: number): string;
  /** Whether a pointer stops at it. */
  solid(x: number, y: number, z: number): boolean;
  /** Whether it is a part-block of the ground, which building on makes whole. */
  partial(x: number, y: number, z: number): boolean;
  /** Whether a placed block takes the block's place (a plant, a part-block all but flat), rather than being built beside it. */
  replaceable(x: number, y: number, z: number): boolean;
}

/** The planet's JSON for a chunk's nodes, read. */
export function decodeNodes(json: unknown): MapblockNodes {
  const j = (json ?? {}) as { names?: unknown; nodes?: unknown; passable?: unknown; partial?: unknown; replaceable?: unknown };
  const names = Array.isArray(j.names) ? j.names.map(String) : ['air'];
  const passable = new Set(Array.isArray(j.passable) ? j.passable.map(String) : ['air']);
  const partial = new Set(Array.isArray(j.partial) ? j.partial.map(String) : []);
  const replaceable = new Set(Array.isArray(j.replaceable) ? j.replaceable.map(String) : []);
  const bin = typeof j.nodes === 'string' ? atob(j.nodes) : '';
  const content = new Uint16Array(4096);
  for (let i = 0; i < 4096 && i * 2 + 1 < bin.length; i++) content[i] = bin.charCodeAt(i * 2) | (bin.charCodeAt(i * 2 + 1) << 8);
  const solidName = names.map((n) => !passable.has(n));
  const at = (x: number, y: number, z: number) => content[(z * 16 + y) * 16 + x]!;
  return {
    name: (x, y, z) => names[at(x, y, z)] ?? 'air',
    solid: (x, y, z) => solidName[at(x, y, z)] ?? false,
    partial: (x, y, z) => partial.has(names[at(x, y, z)] ?? 'air'),
    replaceable: (x, y, z) => replaceable.has(names[at(x, y, z)] ?? 'air'),
  };
}

/** A change the planet's room told of: a chunk of a region, by its position in 16-block chunks; null for anything else. */
export function changeOf(path: string, intent: unknown): { region: string; chunk: [number, number, number]; version: number } | null {
  const m = /^planet\/area\/([a-z0-9-]+)\/chunk\/(-?\d+)\/(-?\d+)\/(-?\d+)$/.exec(path);
  if (!m) return null;
  const v = (intent as { version?: unknown } | null)?.version;
  return { region: m[1]!, chunk: [Number(m[2]), Number(m[3]), Number(m[4])], version: typeof v === 'number' ? v : 0 };
}
